// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAccount Read the administrator account
	// (GET /api/v1/account)
	GetAccount(w http.ResponseWriter, r *http.Request)
	// UpdateAccount Change the administrator username or password
	// (PATCH /api/v1/account)
	UpdateAccount(w http.ResponseWriter, r *http.Request, params UpdateAccountParams)
	// UpdateAccountLocale Persist the administrator language preference
	// (PUT /api/v1/account/locale)
	UpdateAccountLocale(w http.ResponseWriter, r *http.Request, params UpdateAccountLocaleParams)
	// RevokeAllSessions Revoke every administrator session
	// (DELETE /api/v1/account/sessions)
	RevokeAllSessions(w http.ResponseWriter, r *http.Request, params RevokeAllSessionsParams)
	// DisableTOTP Disable TOTP and revoke all sessions
	// (DELETE /api/v1/account/totp)
	DisableTOTP(w http.ResponseWriter, r *http.Request, params DisableTOTPParams)
	// ConfirmTOTPEnrollment Confirm and enable TOTP
	// (POST /api/v1/account/totp)
	ConfirmTOTPEnrollment(w http.ResponseWriter, r *http.Request, params ConfirmTOTPEnrollmentParams)
	// StartTOTPEnrollment Start TOTP enrollment
	// (POST /api/v1/account/totp/enrollment)
	StartTOTPEnrollment(w http.ResponseWriter, r *http.Request, params StartTOTPEnrollmentParams)
	// GetAgentEnrollment Read automatic Agent enrollment settings
	// (GET /api/v1/agent-enrollment)
	GetAgentEnrollment(w http.ResponseWriter, r *http.Request)
	// UpdateAgentEnrollment Enable or disable automatic Agent enrollment
	// (PUT /api/v1/agent-enrollment)
	UpdateAgentEnrollment(w http.ResponseWriter, r *http.Request, params UpdateAgentEnrollmentParams)
	// RotateAgentEnrollmentKey Generate or rotate the automatic Agent enrollment key
	// (POST /api/v1/agent-enrollment/key)
	RotateAgentEnrollmentKey(w http.ResponseWriter, r *http.Request, params RotateAgentEnrollmentKeyParams)
	// GetAgentConfiguration Read the current complete desired Agent configuration
	// (GET /api/v1/agent/configuration)
	GetAgentConfiguration(w http.ResponseWriter, r *http.Request)
	// PollAgent Report Agent state and read current control state
	// (POST /api/v1/agent/control)
	PollAgent(w http.ResponseWriter, r *http.Request)
	// RegisterAgent Register a new Agent and node
	// (POST /api/v1/agent/enroll)
	RegisterAgent(w http.ResponseWriter, r *http.Request)
	// Login Start an administrator session
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current administrator session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request, params LogoutParams)
	// GetAuthenticatedSession Read the current administrator session
	// (GET /api/v1/auth/session)
	GetAuthenticatedSession(w http.ResponseWriter, r *http.Request)
	// GetNetworkObservationSettings Read global lightweight address discovery services
	// (GET /api/v1/network-observation-settings)
	GetNetworkObservationSettings(w http.ResponseWriter, r *http.Request)
	// UpdateNetworkObservationSettings Replace global lightweight address discovery services
	// (PUT /api/v1/network-observation-settings)
	UpdateNetworkObservationSettings(w http.ResponseWriter, r *http.Request, params UpdateNetworkObservationSettingsParams)
	// ListNetworkProxies List centrally managed network proxies without revealing passwords
	// (GET /api/v1/network-proxies)
	ListNetworkProxies(w http.ResponseWriter, r *http.Request)
	// CreateNetworkProxy Create a centrally managed network proxy
	// (POST /api/v1/network-proxies)
	CreateNetworkProxy(w http.ResponseWriter, r *http.Request, params CreateNetworkProxyParams)
	// DeleteNetworkProxy Delete an unreferenced network proxy
	// (DELETE /api/v1/network-proxies/{proxyId})
	DeleteNetworkProxy(w http.ResponseWriter, r *http.Request, proxyId ProxyId, params DeleteNetworkProxyParams)
	// UpdateNetworkProxy Replace network proxy settings and explicitly keep, replace, or clear its password
	// (PUT /api/v1/network-proxies/{proxyId})
	UpdateNetworkProxy(w http.ResponseWriter, r *http.Request, proxyId ProxyId, params UpdateNetworkProxyParams)
	// ListNodes List registered nodes
	// (GET /api/v1/nodes)
	ListNodes(w http.ResponseWriter, r *http.Request)
	// DeleteNode Permanently delete a node and all owned data
	// (DELETE /api/v1/nodes/{nodeId})
	DeleteNode(w http.ResponseWriter, r *http.Request, nodeId NodeId, params DeleteNodeParams)
	// UpdateNode Update node monitoring state
	// (PATCH /api/v1/nodes/{nodeId})
	UpdateNode(w http.ResponseWriter, r *http.Request, nodeId NodeId, params UpdateNodeParams)
	// CreateNodeEgress Enable a discovered interface or source-address egress
	// (POST /api/v1/nodes/{nodeId}/egresses)
	CreateNodeEgress(w http.ResponseWriter, r *http.Request, nodeId NodeId, params CreateNodeEgressParams)
	// DeleteNodeEgress Permanently delete a durable network egress
	// (DELETE /api/v1/nodes/{nodeId}/egresses/{egressId})
	DeleteNodeEgress(w http.ResponseWriter, r *http.Request, nodeId NodeId, egressId EgressId, params DeleteNodeEgressParams)
	// UpdateNodeEgress Update a durable network egress
	// (PATCH /api/v1/nodes/{nodeId}/egresses/{egressId})
	UpdateNodeEgress(w http.ResponseWriter, r *http.Request, nodeId NodeId, egressId EgressId, params UpdateNodeEgressParams)
	// GetNodeNetwork Read the latest network inventory, candidates, and configured egresses
	// (GET /api/v1/nodes/{nodeId}/network)
	GetNodeNetwork(w http.ResponseWriter, r *http.Request, nodeId NodeId)
	// RevokeNode Permanently revoke a node Agent credential
	// (POST /api/v1/nodes/{nodeId}/revoke)
	RevokeNode(w http.ResponseWriter, r *http.Request, nodeId NodeId, params RevokeNodeParams)
	// StopNodeSyncSession Stop the current temporary node sync session
	// (DELETE /api/v1/nodes/{nodeId}/sync-session)
	StopNodeSyncSession(w http.ResponseWriter, r *http.Request, nodeId NodeId, params StopNodeSyncSessionParams)
	// StartNodeSyncSession Start or replace a ten-minute temporary node sync session
	// (POST /api/v1/nodes/{nodeId}/sync-session)
	StartNodeSyncSession(w http.ResponseWriter, r *http.Request, nodeId NodeId, params StartNodeSyncSessionParams)
	// GetSystemStatus Read center status
	// (GET /api/v1/system/status)
	GetSystemStatus(w http.ResponseWriter, r *http.Request)
}

