// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAccount Read the administrator account
	// (GET /api/v1/account)
	GetAccount(ctx context.Context, request GetAccountRequestObject) (GetAccountResponseObject, error)
	// UpdateAccount Change the administrator username or password
	// (PATCH /api/v1/account)
	UpdateAccount(ctx context.Context, request UpdateAccountRequestObject) (UpdateAccountResponseObject, error)
	// UpdateAccountLocale Persist the administrator language preference
	// (PUT /api/v1/account/locale)
	UpdateAccountLocale(ctx context.Context, request UpdateAccountLocaleRequestObject) (UpdateAccountLocaleResponseObject, error)
	// RevokeAllSessions Revoke every administrator session
	// (DELETE /api/v1/account/sessions)
	RevokeAllSessions(ctx context.Context, request RevokeAllSessionsRequestObject) (RevokeAllSessionsResponseObject, error)
	// DisableTOTP Disable TOTP and revoke all sessions
	// (DELETE /api/v1/account/totp)
	DisableTOTP(ctx context.Context, request DisableTOTPRequestObject) (DisableTOTPResponseObject, error)
	// ConfirmTOTPEnrollment Confirm and enable TOTP
	// (POST /api/v1/account/totp)
	ConfirmTOTPEnrollment(ctx context.Context, request ConfirmTOTPEnrollmentRequestObject) (ConfirmTOTPEnrollmentResponseObject, error)
	// StartTOTPEnrollment Start TOTP enrollment
	// (POST /api/v1/account/totp/enrollment)
	StartTOTPEnrollment(ctx context.Context, request StartTOTPEnrollmentRequestObject) (StartTOTPEnrollmentResponseObject, error)
	// GetAgentEnrollment Read automatic Agent enrollment settings
	// (GET /api/v1/agent-enrollment)
	GetAgentEnrollment(ctx context.Context, request GetAgentEnrollmentRequestObject) (GetAgentEnrollmentResponseObject, error)
	// UpdateAgentEnrollment Enable or disable automatic Agent enrollment
	// (PUT /api/v1/agent-enrollment)
	UpdateAgentEnrollment(ctx context.Context, request UpdateAgentEnrollmentRequestObject) (UpdateAgentEnrollmentResponseObject, error)
	// RotateAgentEnrollmentKey Generate or rotate the automatic Agent enrollment key
	// (POST /api/v1/agent-enrollment/key)
	RotateAgentEnrollmentKey(ctx context.Context, request RotateAgentEnrollmentKeyRequestObject) (RotateAgentEnrollmentKeyResponseObject, error)
	// GetAgentConfiguration Read the current complete desired Agent configuration
	// (GET /api/v1/agent/configuration)
	GetAgentConfiguration(ctx context.Context, request GetAgentConfigurationRequestObject) (GetAgentConfigurationResponseObject, error)
	// PollAgent Report Agent state and read current control state
	// (POST /api/v1/agent/control)
	PollAgent(ctx context.Context, request PollAgentRequestObject) (PollAgentResponseObject, error)
	// RegisterAgent Register a new Agent and node
	// (POST /api/v1/agent/enroll)
	RegisterAgent(ctx context.Context, request RegisterAgentRequestObject) (RegisterAgentResponseObject, error)
	// Login Start an administrator session
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current administrator session
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetAuthenticatedSession Read the current administrator session
	// (GET /api/v1/auth/session)
	GetAuthenticatedSession(ctx context.Context, request GetAuthenticatedSessionRequestObject) (GetAuthenticatedSessionResponseObject, error)
	// GetNetworkObservationSettings Read global lightweight address discovery services
	// (GET /api/v1/network-observation-settings)
	GetNetworkObservationSettings(ctx context.Context, request GetNetworkObservationSettingsRequestObject) (GetNetworkObservationSettingsResponseObject, error)
	// UpdateNetworkObservationSettings Replace global lightweight address discovery services
	// (PUT /api/v1/network-observation-settings)
	UpdateNetworkObservationSettings(ctx context.Context, request UpdateNetworkObservationSettingsRequestObject) (UpdateNetworkObservationSettingsResponseObject, error)
	// ListNetworkProxies List centrally managed network proxies without revealing passwords
	// (GET /api/v1/network-proxies)
	ListNetworkProxies(ctx context.Context, request ListNetworkProxiesRequestObject) (ListNetworkProxiesResponseObject, error)
	// CreateNetworkProxy Create a centrally managed network proxy
	// (POST /api/v1/network-proxies)
	CreateNetworkProxy(ctx context.Context, request CreateNetworkProxyRequestObject) (CreateNetworkProxyResponseObject, error)
	// DeleteNetworkProxy Delete an unreferenced network proxy
	// (DELETE /api/v1/network-proxies/{proxyId})
	DeleteNetworkProxy(ctx context.Context, request DeleteNetworkProxyRequestObject) (DeleteNetworkProxyResponseObject, error)
	// UpdateNetworkProxy Replace network proxy settings and explicitly keep, replace, or clear its password
	// (PUT /api/v1/network-proxies/{proxyId})
	UpdateNetworkProxy(ctx context.Context, request UpdateNetworkProxyRequestObject) (UpdateNetworkProxyResponseObject, error)
	// ListNodes List registered nodes
	// (GET /api/v1/nodes)
	ListNodes(ctx context.Context, request ListNodesRequestObject) (ListNodesResponseObject, error)
	// DeleteNode Permanently delete a node and all owned data
	// (DELETE /api/v1/nodes/{nodeId})
	DeleteNode(ctx context.Context, request DeleteNodeRequestObject) (DeleteNodeResponseObject, error)
	// UpdateNode Update node monitoring state
	// (PATCH /api/v1/nodes/{nodeId})
	UpdateNode(ctx context.Context, request UpdateNodeRequestObject) (UpdateNodeResponseObject, error)
	// CreateNodeEgress Enable a discovered interface or source-address egress
	// (POST /api/v1/nodes/{nodeId}/egresses)
	CreateNodeEgress(ctx context.Context, request CreateNodeEgressRequestObject) (CreateNodeEgressResponseObject, error)
	// DeleteNodeEgress Permanently delete a durable network egress
	// (DELETE /api/v1/nodes/{nodeId}/egresses/{egressId})
	DeleteNodeEgress(ctx context.Context, request DeleteNodeEgressRequestObject) (DeleteNodeEgressResponseObject, error)
	// UpdateNodeEgress Update a durable network egress
	// (PATCH /api/v1/nodes/{nodeId}/egresses/{egressId})
	UpdateNodeEgress(ctx context.Context, request UpdateNodeEgressRequestObject) (UpdateNodeEgressResponseObject, error)
	// GetNodeNetwork Read the latest network inventory, candidates, and configured egresses
	// (GET /api/v1/nodes/{nodeId}/network)
	GetNodeNetwork(ctx context.Context, request GetNodeNetworkRequestObject) (GetNodeNetworkResponseObject, error)
	// RevokeNode Permanently revoke a node Agent credential
	// (POST /api/v1/nodes/{nodeId}/revoke)
	RevokeNode(ctx context.Context, request RevokeNodeRequestObject) (RevokeNodeResponseObject, error)
	// StopNodeSyncSession Stop the current temporary node sync session
	// (DELETE /api/v1/nodes/{nodeId}/sync-session)
	StopNodeSyncSession(ctx context.Context, request StopNodeSyncSessionRequestObject) (StopNodeSyncSessionResponseObject, error)
	// StartNodeSyncSession Start or replace a ten-minute temporary node sync session
	// (POST /api/v1/nodes/{nodeId}/sync-session)
	StartNodeSyncSession(ctx context.Context, request StartNodeSyncSessionRequestObject) (StartNodeSyncSessionResponseObject, error)
	// GetSystemStatus Read center status
	// (GET /api/v1/system/status)
	GetSystemStatus(ctx context.Context, request GetSystemStatusRequestObject) (GetSystemStatusResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetAccount operation middleware
func (sh *strictHandler) GetAccount(w http.ResponseWriter, r *http.Request) {
	var request GetAccountRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetAccount(ctx, request.(GetAccountRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetAccount")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetAccountResponseObject); ok {
		if err := validResponse.VisitGetAccountResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

